// Checks the TypeScript protocol implementation against vectors generated by the Rust one
// (crates/proto/tests/vectors.rs).

import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { test } from "node:test";

import { fromUtf8, utf8 } from "../src/core/encoding.ts";
import { boxRecipient, SignKey, verify } from "../src/core/keys.ts";
import {
  coversDomain,
  decodeInvite,
  encodeInvite,
  type Envelope,
  openEnvelope,
  parseSelector,
  sealEnvelope,
  selectorToString,
} from "../src/core/protocol.ts";
import { messageBytes, pairingCode, requestBytes } from "../src/core/signing.ts";

const v = JSON.parse(readFileSync(new URL("../../testdata/vectors/proto.json", import.meta.url), "utf8"));

test("Ed25519 keys and deterministic signatures match Rust", async () => {
  const owner = await SignKey.fromSeed(v.owner_seed);
  assert.equal(owner.publicKey, v.owner_public);
  const r = v.request;
  const bytes = await requestBytes(r.method, r.path, utf8(r.body), r.time, r.nonce);
  assert.equal(fromUtf8(bytes), r.signed_text);
  assert.equal(await owner.sign(bytes), r.signature);
  assert.ok(await verify(v.owner_public, bytes, r.signature));
  assert.ok(!(await verify(v.consumer_public, bytes, r.signature)));

  const consumer = await SignKey.fromSeed(v.consumer_seed);
  assert.equal(await consumer.sign(await messageBytes("grant-id-0001", utf8("ciphertext"))), v.message_signature);
});

test("age identities, envelopes and pairing codes interoperate", async () => {
  assert.equal(await boxRecipient(v.consumer_box_identity), v.consumer_box);
  assert.deepEqual(await openEnvelope(v.envelope as Envelope, v.owner_public, v.consumer_box_identity), v.snapshot);

  const tampered = { ...v.envelope, version: v.envelope.version + 1 };
  await assert.rejects(openEnvelope(tampered, v.owner_public, v.consumer_box_identity), /signature/);

  const owner = await SignKey.fromSeed(v.owner_seed);
  const resealed = await sealEnvelope("g-ts-000001", 7, v.snapshot, v.consumer_box, owner);
  assert.deepEqual(await openEnvelope(resealed, v.owner_public, v.consumer_box_identity), v.snapshot);

  assert.equal(
    await pairingCode(v.owner_public, v.owner_box, v.consumer_public, v.consumer_box, v.invite.token),
    v.pairing_code,
  );
});

test("invites and selectors", () => {
  assert.equal(encodeInvite(v.invite), v.invite_encoded);
  assert.deepEqual(decodeInvite(v.invite_encoded), v.invite);
  for (const c of v.selectors) {
    const s = parseSelector(c.text);
    assert.equal(selectorToString(s), c.canonical);
    for (const d of c.matches) assert.ok(coversDomain(s, d), d);
    for (const d of c.rejects) assert.ok(!coversDomain(s, d), d);
  }
  for (const bad of v.invalid_selectors) assert.throws(() => parseSelector(bad), bad);
});
